1: <script>
2: import template from '@/mixins/ListTemplate.js'
3: import listMixins from '@/mixins/listMixins'
4: import { navigateToTodoTask } from '@/utils/ruoyi'
5: export default {
6:   name: 'Deploy',
7:   template: template,
8:   mixins: [listMixins],
9:   data() {
10:     return {
11:       primaryKey: 'taskId',
12:       businessName: 'task',
13:       moduleName: 'flowable',
14:       busCodeOptions: [],
15:       busCodeSelectLoading: false,
16:       busCodeRemoteTimer: null,
17:       busCodeStickyOption: null,
18:       busCodeTypedKeyword: '',
19:       // 查询参数
20:       queryParams: {
21:         pageNum: 1,
22:         pageSize: 10,
23:         busCode: undefined,
24:         category: undefined,
25:         submitTittle: undefined,
26:         deployTime: undefined,
27:         keyWord: undefined
28:       },
29:       selectable: false
30:     }
31:   },
32:   watch: {
33:     'queryParams.busCode'(val, oldVal) {
34:       if (val === undefined || val === null || val === '') {
35:         this.busCodeStickyOption = null
36:         this.busCodeTypedKeyword = ''
37:         const had = oldVal !== undefined && oldVal !== null && oldVal !== ''
38:         if (had) {
39:           this.fetchBusCodeMenu()
40:         }
41:       }
42:     }
43:   },
44:   beforeDestroy() {
45:     if (this.busCodeRemoteTimer) {
46:       clearTimeout(this.busCodeRemoteTimer)
47:     }
48:   },
49:   methods: {
50:     fetchBusCodeMenu(keyWord) {
51:       this.busCodeSelectLoading = true
52:       // 后端 listBusCodeMenuByKeyWord 使用 @RequestBody String，必须用 text/plain 直接传纯文本 keyWord；
53:       // 传 JSON 对象/带引号字符串会被当作字面量导致模糊匹配不到，下拉永远为空。
54:       // 传空格（后端 trim 后相当于空关键词）可拉取全部业务类型。
55:       const kw = keyWord == null || keyWord === '' ? ' ' : String(keyWord)
56:       this.$post('/system/menu/listBusCodeMenuByKeyWord', kw, {
57:         headers: { 'Content-Type': 'text/plain;charset=UTF-8' }
58:       })
59:         .then((res) => {
60:           const rows = res.data || []
61:           let list = rows.map((e) => ({
62:             ...e,
63:             dictLabel: e.menuName,
64:             dictValue: e.busCode
65:           }))
66:           const v = this.queryParams.busCode
67:           if (v && this.busCodeStickyOption && String(this.busCodeStickyOption.dictValue) === String(v)) {
68:             if (!list.some((i) => String(i.dictValue) === String(v))) {
69:               list = [this.busCodeStickyOption, ...list]
70:             }
71:           }
72:           if (v && !this.busCodeStickyOption) {
73:             const hit = list.find((i) => String(i.dictValue) === String(v))
74:             if (hit) {
75:               this.busCodeStickyOption = { ...hit }
76:             }
77:           }
78:           this.busCodeOptions = list
79:         })
80:         .finally(() => {
81:           this.busCodeSelectLoading = false
82:         })
83:     },
84:     remoteSearchBusCode(query) {
85:       this.busCodeTypedKeyword = (query || '').trim()
86:       if (this.busCodeRemoteTimer) {
87:         clearTimeout(this.busCodeRemoteTimer)
88:         this.busCodeRemoteTimer = null
89:       }
90:       const q = (query || '').trim()
91:       if (!q) {
92:         this.fetchBusCodeMenu()
93:         return
94:       }
95:       this.busCodeRemoteTimer = setTimeout(() => {
96:         this.busCodeRemoteTimer = null
97:         this.fetchBusCodeMenu(q)
98:       }, 300)
99:     },
100:     handleBusCodeChange(val) {
101:       this.busCodeTypedKeyword = ''
102:       if (val === undefined || val === null || val === '') {
103:         this.busCodeStickyOption = null
104:         return
105:       }
106:       const hit = this.busCodeOptions.find((o) => String(o.dictValue) === String(val))
107:       this.busCodeStickyOption = hit ? { ...hit } : null
108:     },
109:     // 点击查询：若用户只输入了业务类型名称但未从下拉中选中，则按名称解析为 busCode，
110:     // 避免“输入内容后点查询就清空、仍无数据”的问题（后端仅支持按 busCode 精确过滤）。
111:     handleQuery() {
112:       const empty = (v) => v === undefined || v === null || v === ''
113:       const kw = (this.busCodeTypedKeyword || '').trim()
114:       if (empty(this.queryParams.busCode) && kw) {
115:         this.resolveBusCodeByKeyword(kw).then((hit) => {
116:           // 禅道6081【苏州房产】首页：按业务类型查询不生效
117:           // 解析不到唯一业务类型时不能静默按全量查询，否则用户会误以为“查询条件没生效”
118:           if (!hit) {
119:             this.msgWarning('未匹配到业务类型，请从下拉列表中选择')
120:             return
121:           }
122:           this.queryParams.busCode = hit.dictValue
123:           this.busCodeStickyOption = { ...hit }
124:           if (!this.busCodeOptions.some((o) => String(o.dictValue) === String(hit.dictValue))) {
125:             this.busCodeOptions = [hit, ...this.busCodeOptions]
126:           }
127:           this.queryParams.pageNum = 1
128:           this.getList()
129:         })
130:         return
131:       }
132:       this.queryParams.pageNum = 1
133:       this.getList()
134:     },
135:     // 根据输入的业务类型名称解析出唯一匹配的选项：优先精确匹配，其次唯一模糊匹配
136:     resolveBusCodeByKeyword(kw) {
137:       const local = this.busCodeOptions || []
138:       const pick = (list) => {
139:         const exact = list.find((o) => String(o.dictLabel) === kw)
140:         if (exact) return exact
141:         const fuzzy = list.filter((o) => String(o.dictLabel).includes(kw))
142:         return fuzzy.length === 1 ? fuzzy[0] : null
143:       }
144:       const localHit = pick(local)
145:       if (localHit) return Promise.resolve(localHit)
146:       // 禅道6081【苏州房产】首页：按业务类型查询不生效
147:       // 后端该接口为 @RequestBody String，而 $get 会被请求层统一改写成 POST+JSON body，
148:       // 后端实际收到 {"keyWord":"xx"} 这段字面量导致 like 匹配 0 条、解析恒失败；
149:       // 此处与下拉保持一致，用 text/plain 直接提交纯文本关键词。
150:       return this.$post('/system/menu/listBusCodeMenuByKeyWord', kw, {
151:         headers: { 'Content-Type': 'text/plain;charset=UTF-8' }
152:       })
153:         .then((res) => {
154:           const list = (res.data || []).map((e) => ({
155:             ...e,
156:             dictLabel: e.menuName,
157:             dictValue: e.busCode
158:           }))
159:           return pick(list)
160:         })
161:         .catch(() => null)
162:     },
163:     handleBusCodeSelectVisible(visible) {
164:       if (visible) return
165:       if (this.busCodeRemoteTimer) {
166:         clearTimeout(this.busCodeRemoteTimer)
167:         this.busCodeRemoteTimer = null
168:       }
169:       this.fetchBusCodeMenu()
170:     },
171:     initDict() {
172:       this.fetchBusCodeMenu()
173:     },
174:     // 跳转到处理页面
175:     handleProcess(row) {
176:       navigateToTodoTask(this.$router, row)
177:     }
178:   },
179:   computed: {
180:     columns: function () {
181:       return [
182:         {
183:           label: '业务类型',
184:           prop: 'menuName',
185:           function: this.handleProcess,
186:           type: 'link'
187:         },
188:         {
189:           label: '主题',
190:           prop: 'submitTittle'
191:         },
192:         {
193:           label: '任务名称',
194:           prop: 'taskName'
195:         },
196:         {
197:           label: '发起人',
198:           prop: 'startUserName'
199:         },
200:         {
201:           label: '发起时间',
202:           prop: 'startTime'
203:         }
204:       ]
205:     },
206:     formItems: function () {
207:       return [{
208:         label: '业务类型',
209:         model: 'busCode',
210:         type: 'select',
211:         attrs: {
212:           placeholder: '请输入关键词搜索业务类型',
213:           options: this.busCodeOptions,
214:           filterable: true,
215:           remote: true,
216:           'remote-method': this.remoteSearchBusCode,
217:           loading: this.busCodeSelectLoading
218:         },
219:         listeners: {
220:           change: this.handleBusCodeChange,
221:           'visible-change': this.handleBusCodeSelectVisible
222:         }
223:       }, {
224:         label: '发起时间',
225:         model: 'deployTime',
226:         type: 'date',
227:         attrs: {
228:           placeholder: '选择时间',
229:           'value-format': 'yyyy-MM-dd'
230:         }
231:       }, {
232:         label: '主题',
233:         model: 'submitTittle',
234:         type: 'input',
235:         attrs: {
236:           placeholder: '请输入主题'
237:         }
238:       }, {
239:         label: '发起人',
240:         model: 'startUserName',
241:         type: 'input',
242:         attrs: {
243:           placeholder: '请输入发起人'
244:         }
245:       }]
246:     },
247:     operationButtons: function () {
248:       return []
249:     },
250:     // 表格操作列按钮配置
251:     buttons: function () {
252:       return [
253:         {
254:           label: '处理',
255:           permissionType: 'view',
256:           function: this.handleProcess,
257:           permission: false, // 默认情况下列表查看按钮不做权限控制
258:           attrs: {
259:             type: 'primary'
260:           }
261:         }
262:       ]
263:     },
264:     apiSuffix: function () {
